const pendingList = localStorage.values.pendingPayments || [];
const enteredAmount = Number(numAmount.value);
const invoiceId = isAdvance ? null : String(stateSelectedInvoice.value?.id || '');

// 2. "Bulletproof" Offline ID Generation
const timestamp = moment().format('MMDD-HHmmss'); 
const randomStr = Math.random().toString(36).substring(2, 5).toUpperCase();
const offlineId = `PAY-${stateCurrentUser.value.employee_code}-${timestamp}-${randomStr}`;

// 3. Validation Logic
if (enteredAmount <= 0) {
  utils.showNotification({ 
    title: "Error", 
    description: "Please enter a valid amount.", 
    type: "error" 
  });
  return;
}

// 4. Overpayment Protection (Only if not an Advance)
if (!isAdvance) {
  const dbBalance = Number(stateSelectedInvoice.value?.balance_amount || 0);

  // Check if this same invoice is already being paid in other offline entries
  const alreadyPaidOffline = pendingList
    .filter(p => String(p.invoice_id) === invoiceId)
    .reduce((sum, p) => sum + Number(p.amount || 0), 0);

  const realRemainingBalance = dbBalance - alreadyPaidOffline;

  if (enteredAmount > (realRemainingBalance + 0.01)) {
    utils.showNotification({ 
      title: "Overpayment Error", 
      description: "Remaining balance is ₹" + realRemainingBalance.toFixed(2), 
      type: "error" 
    });
    return;
  }
}

// 5. Create Payment Object
const newPayment = {
  offline_id: offlineId, 
  uid: offlineId, 
  customer_id: stateSelectedCust.value?.id,
  customer_name: stateSelectedCust.value?.customer_name || "Unknown",
  invoice_id: invoiceId, 
  invoice_no: isAdvance ? 'ADVANCE' : stateSelectedInvoice.value?.invoice_number,
