  ai_confidence: stateLastAiConfidence.value || 0, 
  collected_by: stateCurrentUser.value.id,
  timestamp: new Date().toISOString()
};

// 6. Save to Offline Storage & App State
const updatedList = [...pendingList, newPayment];
localStorage.setValue('pendingPayments', updatedList);
statePendingPayments.setValue(updatedList);

