numAmount.clearValue();
selPaymentMode.clearValue();
selBankName.clearValue();
txtReference.clearValue();
dtpPaymentDate.clearValue();
selDepositBank.clearValue();
stateLastAiConfidence.setValue(0); 
if (typeof bankrefno !== 'undefined') bankrefno.clearValue();

