                            </div>
                            <div style="font-size:11px; color:#A0A0A0;">${c.oldest_invoice_days} days overdue</div>
                        </td>
                        <td align="right" style="padding:12px 0; border-bottom:${i === 4 ? 'none' : '1px solid #333333'}; font-size:14px; font-weight:700; color:#F44336;">₹${Number(c.overdue_amount).toLocaleString('en-IN', {maximumFractionDigits:0})}</td>
                    </tr>
                `).join('') 
            }}
        </table>
    </div>

</div>

